#!/usr/bin/env node
const { execSync } = require('child_process');
const { appendEvent } = require('./city-ledger');

function getGaps() {
  const gapsRaw = execSync('node .fastops/city-brief.js --gaps --json').toString();
  return JSON.parse(gapsRaw);
}

function postToMarketplace(gap) {
  const cmd = `node .fastops/city-marketplace.js --post '${JSON.stringify(gap)}'`;
  return execSync(cmd).toString();
}

function main(dryRun = false) {
  const gaps = getGaps().filter(g => g.severity === 'high');
  
  gaps.forEach(gap => {
    if (dryRun) {
      console.log(`[DRY RUN] Would post gap: ${gap.title}`);
    } else {
      const result = postToMarketplace(gap);
      appendEvent({
        type: 'reflex-arc',
        action: 'auto-heal',
        data: { gap, result }
      });
      console.log(`Posted gap: ${gap.title}`);
    }
  });
}

const dryRun = process.argv.includes('--dry-run');
main(dryRun);

